class MaxMaximalCocktailsCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.SMT

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        nodes_list: List[int] = data['nodes']
        edges_list: List[tuple] = data['edges']
        cnt_maximal_cocktails: int = data['cnt_maximal_cocktails']

        # Build adjacency sets
        adj: Dict[int, set] = {u: set() for u in nodes_list}
        for u, v in edges_list:
            adj[u].add(v)
            adj[v].add(u)

        # 1) Find two isolates
        isolates = [u for u in nodes_list if not adj[u]]
        if len(isolates) >= 2:
            u, v = sorted(isolates)[:2]
            new_edge = (u, v)
        else:
            # 2) Find non-edge pair with identical neighbor sets (true twins)
            new_edge = None
            n = len(nodes_list)
            nodes_sorted = sorted(nodes_list)
            node_idx = {u: i for i, u in enumerate(nodes_sorted)}
            # Precompute neighbor signatures
            neigh_sig = {u: frozenset(adj[u]) for u in nodes_sorted}
            for i in range(n):
                u = nodes_sorted[i]
                for j in range(i+1, n):
                    v = nodes_sorted[j]
                    if v not in adj[u]:
                        # non-edge
                        if neigh_sig[u] == neigh_sig[v]:
                            new_edge = (u, v)
                            break
                if new_edge:
                    break
            # 3) Fallback: pick smallest non-edge
            if new_edge is None:
                for i in range(n):
                    u = nodes_sorted[i]
                    for j in range(i+1, n):
                        v = nodes_sorted[j]
                        if v not in adj[u]:
                            new_edge = (u, v)
                            break
                    if new_edge:
                        break

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=new_edge, type='custom')]
        )

