from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class MaxMaximalCocktailsCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.SMT

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        nodes_list = data['nodes']
        edges_list = data['edges']
        current_cnt = data['cnt_maximal_cocktails']

        # helper to count maximal independent sets by bitmasks
        def count_maximals(nodes, edges):
            n = len(nodes)
            idx = {node: i for i, node in enumerate(nodes)}
            # build adjacency mask
            adj = [0]*n
            for u, v in edges:
                i, j = idx[u], idx[v]
                adj[i] |= 1<<j
                adj[j] |= 1<<i
            indep = []
            # enumerate all subsets
            for s in range(1<<n):
                ok = True
                # quick independent check
                for i in range(n):
                    if (s>>i)&1:
                        # if any neighbor in s, not independent
                        if adj[i] & s:
                            ok = False
                            break
                if ok:
                    indep.append(s)
            # count maximals
            cnt = 0
            full_mask = (1<<n)-1
            for s in indep:
                # if there is any vertex i not in s that can be added, it's not maximal
                can_extend = False
                rem = full_mask ^ s
                # test each bit in rem
                t = rem
                while t and not can_extend:
                    i = (t & -t).bit_length()-1
                    t &= t-1
                    if (adj[i] & s) == 0:
                        can_extend = True
                if not can_extend:
                    cnt += 1
            return cnt

        # build a set for quick lookup of existing edges
        existing = set()
        for u, v in edges_list:
            existing.add((u, v))
            existing.add((v, u))
        # iterate all missing edges
        new_edge = None
        L = len(nodes_list)
        for i in range(L):
            for j in range(i+1, L):
                u, v = nodes_list[i], nodes_list[j]
                if (u, v) in existing:
                    continue
                # test this move
                test_edges = edges_list + [(u, v)]
                cnt2 = count_maximals(nodes_list, test_edges)
                if cnt2 >= current_cnt:
                    new_edge = (u, v)
                    break
            if new_edge is not None:
                break
        # if none legal, pick first missing
        if new_edge is None:
            for i in range(L):
                for j in range(i+1, L):
                    u, v = nodes_list[i], nodes_list[j]
                    if (u, v) not in existing:
                        new_edge = (u, v)
                        break
                if new_edge is not None:
                    break
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=new_edge, type='custom')]
        )

