from pydantic import BaseModel  
from typing import List, Optional, Dict, Any  
from enum import Enum  
from abc import abstractmethod  

from system.message import Info  
from system.message import BaseMessageDataType  
from model.strategy_type import StrategyType  
from model.base import BaseStrategy  

class MaxMaximalCocktailsCustomStrategy:  
    def __init__(self, model: BaseStrategy):  
        self._model = model  
        self.name = self._model.name  
        self.history = self._model.history  
        self.strategy_type = StrategyType.SMT  

    def update_model_field(self, field_name: str, value: Any):  
        if hasattr(self._model, field_name):  
            setattr(self._model, field_name, value)  

    def receive_message(self, message: Info) -> Info:  
        data = message.message[0].data  
        nodes_list = data['nodes']  
        edges_list = data['edges']  
        cnt_maximal_cocktails = data['cnt_maximal_cocktails']  
        # Map nodes to 0..n-1  
        idx = {node: i for i, node in enumerate(nodes_list)}  
        n = len(nodes_list)  
        # Build adjacency matrix  
        adj = [[False]*n for _ in range(n)]  
        for u, v in edges_list:  
            i, j = idx[u], idx[v]  
            adj[i][j] = adj[j][i] = True  
        # Function to count maximal independent sets  
        def count_mis(adj_mat):  
            N = len(adj_mat)  
            total = 0  
            # iterate over non-empty subsets  
            for mask in range(1, 1<<N):  
                # check independent  
                ok = True  
                for i in range(N):  
                    if not ok: break  
                    if (mask>>i)&1:  
                        for j in range(i+1, N):  
                            if (mask>>j)&1 and adj_mat[i][j]:  
                                ok = False  
                                break  
                if not ok:  
                    continue  
                # check maximal: no outside vertex can join  
                maximal = True  
                for v in range(N):  
                    if not ((mask>>v)&1):  
                        # v outside; can it be added? it must be nonadjacent to all in mask  
                        good = True  
                        for u in range(N):  
                            if (mask>>u)&1 and adj_mat[u][v]:  
                                good = False  
                                break  
                        if good:  # v can be added -> not maximal  
                            maximal = False  
                            break  
                if maximal:  
                    total += 1  
            return total  
        # Gather missing edges  
        missing = []  
        for i in range(n):  
            for j in range(i+1, n):  
                if not adj[i][j]:  
                    missing.append((i, j))  
        new_edge = None  
        # try each missing edge  
        for i, j in missing:  
            adj[i][j] = adj[j][i] = True  
            new_count = count_mis(adj)  
            # undo  
            adj[i][j] = adj[j][i] = False  
            if new_count >= cnt_maximal_cocktails:  
                new_edge = (nodes_list[i], nodes_list[j])  
                break  
        # if none found, pick first missing (will lose)  
        if new_edge is None and missing:  
            i, j = missing[0]  
            new_edge = (nodes_list[i], nodes_list[j])  
        return Info(  
            sender=self.__class__.__name__,  
            receiver=message.sender,  
            difficulty=message.difficulty,  
            message=[BaseMessageDataType(data=new_edge, type='custom')]  
        )

