from pydantic import BaseModel  
from typing import List, Optional, Dict, Any  
from enum import Enum  
from abc import abstractmethod  

from system.message import Info  
from system.message import BaseMessageDataType  
from model.strategy_type import StrategyType  
from model.base import BaseStrategy

class MaxMaximalCocktailsCustomStrategy:  
    def __init__(self, model: BaseStrategy):  
        self._model = model  
        self.name = self._model.name  
        self.history = self._model.history  
        self.strategy_type = StrategyType.SMT  

    def update_model_field(self, field_name: str, value: Any):  
        if hasattr(self._model, field_name):  
            setattr(self._model, field_name, value)  

    def receive_message(self, message: Info) -> Info:  
        data = message.message[0].data  
        nodes_list = data['nodes']  
        edges_list = data['edges']  
        cnt_maximal_cocktails = data['cnt_maximal_cocktails']  

        # Build adjacency set for existing graph  
        nodes = list(nodes_list)  
        n = len(nodes)  
        edge_set = set()  
        adj = {u: set() for u in nodes}  
        for u, v in edges_list:  
            adj[u].add(v)  
            adj[v].add(u)  
            edge_set.add((u, v) if u < v else (v, u))  

        # If too large, fallback to first missing edge to avoid heavy computation  
        if n > 25:  
            for i in range(n):  
                for j in range(i+1, n):  
                    u, v = nodes[i], nodes[j]  
                    if (u, v) not in edge_set:  
                        new_edge = (u, v)  
                        return Info(  
                            sender=self.__class__.__name__,  
                            receiver=message.sender,  
                            difficulty=message.difficulty,  
                            message=[BaseMessageDataType(data=new_edge, type='custom')]  
                        )  

        # Helper: count maximal independent sets by enumerating maximal cliques in complement via Bron–Kerbosch  
        def count_mis(adj_graph):  
            # Build complement neighbor map  
            comp_neigh = {}  
            all_nodes = set(adj_graph.keys())  
            for u in adj_graph:  
                comp_neigh[u] = all_nodes - adj_graph[u] - {u}  
            # Bron–Kerbosch with pivot  
            count = 0  
            def bk(R, P, X):  
                nonlocal count  
                if not P and not X:  
                    count += 1  
                    return  
                # choose pivot  
                u = next(iter(P | X))  
                for v in list(P - comp_neigh[u]):  
                    bk(R | {v}, P & comp_neigh[v], X & comp_neigh[v])  
                    P.remove(v)  
                    X.add(v)  
            bk(set(), set(adj_graph.keys()), set())  
            return count  

        best_edge = None  
        best_count = -1  
        # Try all missing edges  
        for i in range(n):  
            for j in range(i+1, n):  
                u, v = nodes[i], nodes[j]  
                if (u, v) in edge_set:  
                    continue  
                # add the edge  
                adj[u].add(v)  
                adj[v].add(u)  
                c = count_mis(adj)  
                # remove edge  
                adj[u].remove(v)  
                adj[v].remove(u)  
                if c >= cnt_maximal_cocktails and c > best_count:  
                    best_count = c  
                    best_edge = (u, v)  
                    # if strictly increased, we can stop early  
                    if c > cnt_maximal_cocktails:  
                        break  
            if best_count > cnt_maximal_cocktails:  
                break  

        # If no legal move, pick the first missing edge (we're forced to lose)  
        if best_edge is None:  
            for i in range(n):  
                for j in range(i+1, n):  
                    u, v = nodes[i], nodes[j]  
                    if (u, v) not in edge_set:  
                        best_edge = (u, v)  
                        break  
                if best_edge:  
                    break  

        new_edge = best_edge  
        return Info(  
            sender=self.__class__.__name__,  
            receiver=message.sender,  
            difficulty=message.difficulty,  
            message=[BaseMessageDataType(data=new_edge, type='custom')]  
        )

